    "sange_item_hist_rulle_dag": "In the 1800s (Thursday)",
    "sange_item_hist_rulle_handling": "to roll linen with a mangle board (\"rulle vort tøj\")",
    "sange_item_hist_rulle_redskaber": "a carved wooden mangle board, a wooden roller, a sturdy table",
    "sange_item_hist_rulle_saetning": "In the song they sing: \"when we roll our clothes\" – here they used a heavy mangle board over a rolling pin.",
    "sange_item_hist_rulle_vaerdighed": "The mangle board was often a courtship gift carved with horses and hearts, passed down with love.",
    "sange_item_hist_toerre_dag": "In the 1800s (Wednesday)",
    "sange_item_hist_toerre_handling": "to dry linen on a clothesline between trees",
    "sange_item_hist_toerre_redskaber": "a hemp clothesline, wooden pegs, sun and wind",
    "sange_item_hist_toerre_saetning": "White linens were hung outdoors between tall trees so the sun could naturally bleach the fabric white.",
    "sange_item_hist_toerre_vaerdighed": "Sun and wind were nature’s own bleaching agents, bestowing a fresh, crisp outdoor scent.",
    "sange_item_hist_stryge_dag": "In the 1800s (Friday)",
    "sange_item_hist_stryge_handling": "to iron with a heavy charcoal iron",
    "sange_item_hist_stryge_redskaber": "a cast iron iron with a hinged lid, glowing hot coals",
    "sange_item_hist_stryge_saetning": "The iron was filled with glowing coals from the hearth and weighed several kilos to press across shirts.",
    "sange_item_hist_stryge_vaerdighed": "It required great skill to ensure the flying sparks did not singe the precious white linens.",
    "sange_item_hist_skure_dag": "In the 1800s (Saturday)",
    "sange_item_hist_skure_handling": "to scrub the floor on knees with sand and brush",
    "sange_item_hist_skure_redskaber": "a stiff scrubbing brush, fine white sand, lye water and bucket",
    "sange_item_hist_skure_saetning": "In the song they sing: \"when we scour our floor\" – maids knelt on bare knees scrubbing raw planks with sand.",
    "sange_item_hist_skure_vaerdighed": "The brush and fine white sand made the wood pristine for Sunday, but severely wore down their knees.",
    "sange_msb_title": "Melody & Singing Game in 6/8 Time",
    "sange_msb_sub": "Listen to the melody, feel the steady rhythm of the weekdays, and sing along!",
