    "sange_verse_note_3": "Notice inversion: \"Så gør vi sådan\" (Front field + Verb + Subject).",
    "sange_verse_note_4": "Historically: \"ruller vort tøj\" with mangle board. Today: we fold laundry into neat piles.",
