    "sange_item_tirsdag_handling": "enxaguar e esvaziar a máquina",
    "sange_item_tirsdag_redskaber": "um cesto de roupa, amaciador, centrifugação",
    "sange_item_tirsdag_saetning": "Quando a máquina de lavar termina, o rapaz ajuda a pôr a roupa limpa no cesto.",
    "sange_item_tirsdag_vaerdighed": "Quando crianças e adultos se entreajudam nas tarefas da roupa, reforça-se a harmonia e o espírito de família em casa.",
    "sange_item_onsdag_dag": "Quarta-feira (Agora)",
    "sange_item_onsdag_handling": "secar a roupa no estendal",
    "sange_item_onsdag_redskaber": "um estendal, molas da roupa, uma máquina de secar",
    "sange_item_onsdag_saetning": "Quando sopra uma brisa suave, estendemos a roupa no estendal junto à porta aberta para o jardim.",
    "sange_item_onsdag_vaerdighed": "Secar a roupa ao ar livre poupa energia, protege os tecidos e deixa um aroma fresco e agradável a verão.",
    "sange_item_torsdag_dag": "Quinta-feira (Agora)",
    "sange_item_torsdag_handling": "dobrar e arrumar a roupa",
    "sange_item_torsdag_redskaber": "uma mesa limpa, pilhas organizadas, um guarda-roupa",
    "sange_item_torsdag_saetning": "Quando a roupa está bem seca, dobramo-la com cuidado em pilhas e arrumamo-la no armário.",
    "sange_item_torsdag_vaerdighed": "Um guarda-roupa arrumado traz tranquilidade mental e torna as manhãs mais fáceis e organizadas.",
    "sange_item_fredag_dag": "Sexta-feira (Agora)",
    "sange_item_fredag_handling": "engomar com ferro a vapor",
    "sange_item_fredag_redskaber": "um ferro a vapor ergonómico, uma tábua de engomar, cabides",
    "sange_item_fredag_saetning": "Ao engomar camisas usamos vapor quente para que todos os vincos e rugas fiquem perfeitamente lisos.",
    "sange_item_fredag_vaerdighed": "A roupa bem engomada confere dignidade pessoal, elegância e confiança para o trabalho e momentos de festa.",
    "sange_item_loerdag_dag": "Sábado (Agora)",
    "sange_item_loerdag_handling": "lavar o chão com mopa plana",
    "sange_item_loerdag_redskaber": "uma mopa ergonómica, um balde com água e sabão, detergente multiúsos",
    "sange_item_loerdag_saetning": "Ao sábado lavamos o chão em pé com a mopa, deixando a casa inteira com um aroma fresco e limpo.",
    "sange_item_loerdag_vaerdighed": "Chãos limpos e um lar higiénico formam a base segura e acolhedora da vida de toda a família.",
    "sange_item_soendag_dag": "Domingo (Agora)",
    "sange_item_soendag_handling": "descansar e desfrutar do tempo livre",
    "sange_item_soendag_redskaber": "uma chávena de café, o sofá, tempo em família, serenidade de domingo",
    "sange_item_soendag_saetning": "Ao domingo relaxamos com café e boa conversa numa casa limpa, tranquila e bem cuidada.",
    "sange_item_soendag_vaerdighed": "Depois de uma semana de dedicação, o descanso é plenamente merecido. O lar é o porto seguro da família.",
    "sange_item_enebaerbusk_dag": "O jardim",
    "sange_item_enebaerbusk_handling": "o arbusto de zimbro no jardim",
    "sange_item_enebaerbusk_redskaber": "um arbusto de zimbro sempre-verde, o jardim, a natureza",
    "sange_item_enebaerbusk_saetning": "Pela janela avista-se o verde arbusto de zimbro que dá o nome a esta canção de roda tão querida.",
    "sange_item_enebaerbusk_vaerdighed": "O zimbro mantém-se verde durante todo o inverno e é um símbolo ancestral de vigor, saúde e resistência.",
    "sange_item_hist_vaske_dag": "No século XIX (Segunda-feira)",
    "sange_item_hist_vaske_handling": "lavar na tábua de lavar dentro de uma tina de madeira",
    "sange_item_hist_vaske_redskaber": "uma tábua de lavar de zinco ou madeira, uma tina de carvalho, sabão mole tradicional",
    "sange_item_hist_vaske_saetning": "No século XIX, as mulheres lavavam toda a roupa à mão esfregando com força contra uma tábua canelada.",
    "sange_item_hist_vaske_vaerdighed": "Era uma labuta extremamente dura que esfolava a pele das mãos na água gelada.",
    "sange_item_hist_gruekedel_dag": "No século XIX (A grande barrela)",
    "sange_item_hist_gruekedel_handling": "o caldeirão de barrela: ferver a roupa branca",
    "sange_item_hist_gruekedel_redskaber": "um caldeirão embutido, fogo vivo, lixívia de cinzas, um balde de madeira",
    "sange_item_hist_gruekedel_saetning": "A água era aquecida num caldeirão sobre o fogo para ferver a roupa de cama e a roupa de trabalho.",
    "sange_item_hist_gruekedel_vaerdighed": "O fogo constante e o fumo denso exigiam vigilância permanente e grande força física.",
    "sange_item_hist_rulle_dag": "No século XIX (Quinta-feira)",
    "sange_item_hist_rulle_handling": "prensar o linho com tábua de calandrar („rulle vort tøj“)",
    "sange_item_hist_rulle_redskaber": "uma tábua de calandrar em madeira entalhada, um rolo cilíndrico, uma mesa sólida",
    "sange_item_hist_rulle_saetning": "Na canção canta-se: „Så gør vi sådan, når vi ruller vort tøj“ – usava-se uma pesada tábua de calandrar para alisar o linho.",
    "sange_item_hist_rulle_vaerdighed": "A tábua de calandrar era frequentemente uma prenda de noivado com belos entalhes de cavalos e corações.",
    "sange_item_hist_toerre_dag": "No século XIX (Quarta-feira)",
    "sange_item_hist_toerre_handling": "estender a roupa ao ar livre em cordas entre árvores",
    "sange_item_hist_toerre_redskaber": "uma corda de cânhamo, molas de madeira rústicas, sol e vento",
    "sange_item_hist_toerre_saetning": "O linho branco era estendido no jardim entre árvores frondosas para que o sol branqueasse o tecido naturalmente.",
    "sange_item_hist_toerre_vaerdighed": "O sol e o vento eram os agentes naturais de branqueamento, conferindo à roupa um cheiro fresco e limpo.",
    "sange_item_hist_stryge_dag": "No século XIX (Sexta-feira)",
    "sange_item_hist_stryge_handling": "engomar com um pesado ferro a brasas de carvão",
    "sange_item_hist_stryge_redskaber": "um ferro de engomar de ferro fundido com tampa, brasas incandescentes de carvão",
    "sange_item_hist_stryge_saetning": "O ferro era enchido com brasas vivas do fogo e pesava vários quilos ao ser passado sobre as camisas.",
    "sange_item_hist_stryge_vaerdighed": "Exigia grande perícia para garantir que nenhuma faúlha escapasse e queimasse as roupas de linho fino.",
    "sange_item_hist_skure_dag": "No século XIX (Sábado)",
    "sange_item_hist_skure_handling": "esfregar o soalho de joelhos com areia e escova („skure vort gulv“)",
    "sange_item_hist_skure_redskaber": "uma escova de cerdas duras, areia branca fina, água com lixívia e balde",
    "sange_item_hist_skure_saetning": "Na canção canta-se: „når vi skurer vort gulv“ – as criadas ajoelhavam-se para esfregar as tábuas de pinho com areia.",
    "sange_item_hist_skure_vaerdighed": "A escova e a areia branca deixavam a madeira claríssima para o domingo, mas castigavam duramente joelhos e costas.",
