    "sange_tribute_text": "Хатня праця — це фундамент, на якому тримається все суспільство. Від виснажливої фізичної праці XIX століття до сучасного побуту — саме щоденна турбота жінок і родин створює здоров'я, безпеку та добробут у домівці. Ця пісня вшановує працю, розвиток технологій і людську гідність у кожній хатній справі.",
    "sange_saf_title": "Слухати мелодію пісні-гри",
