    "sange_verse_note_4": "Lịch sử: \"ruller vort tøj\" là dùng tấm gỗ và trục lăn ép đồ. Ngày nay: chúng ta gấp quần áo gọn gàng.",
    "sange_verse_note_5": "Thời xưa dùng bàn ủi than đỏ rực · Ngày nay dùng bàn ủi hơi nước nhẹ nhàng.",
