    "sange_det_finish_desc": "अब तपाईंले दुवै आधुनिक उपकरणहरू र १९ औं शताब्दीका ऐतिहासिक परम्पराहरू जस्तै म्याङ्गल बोर्ड, धुने बोर्ड र कोइला इस्त्रीले \"कपडा समतल बनाउने\" बारे दक्षता हासिल गर्नुभएको छ।",
