    "sange_sb_title": "वाक्य निर्माणकर्ता र पजल: हप्ताको कामहरू सम्बन्धी प्रश्नहरूको उत्तर दिनुहोस्",
    "sange_sb_desc": "\"Hvad laver moren om mandagen?\" जस्ता प्रश्नहरूको जवाफ दिन सिक्नुहोस् (जवाफ: \"Om mandagen vasker hun tøj\")। प्रत्येक बाकसभित्रका प्रश्नहरूले प्रत्येक शब्द कहाँ राख्ने भनेर चरणबद्ध रूपमा मार्गदर्शन गर्दछ!",
    "sange_sb_subtab_puzzle": "१. पजल कार्यहरू (१० प्रश्नहरू)",
