    "sange_match_tag": "जोडा मिलाउने अभ्यास: क्रियापदलाई उपकरणसँग जोड्नुहोस्",
    "sange_match_title": "गीतका क्रियापदहरूलाई ऐतिहासिक र आधुनिक उपकरणहरूसँग जोड्नुहोस्:",
    "sange_match_sub": "बायाँपट्टिको क्रियापदमा क्लिक गर्नुहोस्, र त्यसपछि दायाँपट्टिको सम्बन्धित उपकरणमा क्लिक गर्नुहोस्!",
